        # Since 'a' handles 0, 1, ..., 25 (a, b, ..., z), we need a system for 26, 27...
        # Let's use a simple indexing relative to the counter
        # If count = 26, we want 'a1'. If count = 52, we want 'b2'.

        i = count
        if i == 0: return 'a'

        # Iterative approach for naming (e.g., 26 -> 'a1', 27 -> 'a2', 52 -> 'b2')
        # For simplicity and to match the described pattern ('a', 'b', ..., 'z', 'a1', 'b1', ...)
