class Type:
    def __init__(self, name: str, args: Optional[List['Type']] = None):
        self.name = name
        self.args = args if args is not None else []

    def __repr__(self) -> str:
        return f"<{self.name}>"

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, Type):
            return False
        if self.name != other.name or len(self.args) != len(other.args):
            return False
        return all(t1 == t2 for t1, t2 in zip(self.args, other.args))

    @classmethod
    def make_primitive(cls, name: str) -> 'Type':
        """Creates basic types (int, bool, etc.)"""
