    @classmethod
    def make_var(cls, name: str) -> 'Type':
        """Creates a type variable."""
        return cls(name)

    @classmethod
    def make_func(cls, return_type: 'Type', arg_types: List['Type']) -> 'Type':
        """Creates a function type (->). Args must be placed on the left."""
        return cls(f"->", [return_type] + arg_types)

    @classmethod
    def make_product(cls, types: List['Type']) -> 'Type':
        """Creates a tuple/product type (*)."""
