            # Default case: simple variable or primitive
            return Type.make_var(self._resolve_name(type_t))

        # Fallback for primitives/variables
        return Type.make_var(self._resolve_name(type_t))

    def _resolve_name(self, type_t: Type) -> str:
        """Helper to resolve the actual name of the type for substitution keys."""
        if type_t.name in self.bindings:
