def unify(t1: Type, t2: Type, current_sub: Substitution) -> Substitution:
    """
    Unifies two types t1 and t2, updating the substitution.
    Returns the combined Substitution.
    """
    # 1. Apply current substitution to both types
    t1 = current_sub.apply(current_sub, t1)
    t2 = current_sub.apply(current_sub, t2)

