class Token:
    def __init__(self, type: str, value: Any):
        self.type = type
        self.value = value

def lexer(src: str) -> List[Token]:
    token_specification = [
        ('INT', r'[0-9]+'),
        ('BOOL', r'\b(true|false)\b'),
        ('SYMBOL', r'->|::|\(|\)|\,|\+|-\*|<|\[|\]'),
        ('NAME', r'[a-z_][a-z0-9\._\']*'),
        ('SKIP', r'[ \t\r\n]+'),
    ]
    tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)

    tokens: List[Token] = []

    for match in re.finditer(tok_regex, src):
        tok_type = match.lastgroup
        value = match.group(0)

        if tok_type == 'SKIP':
            continue

        if tok_type == 'INT':
            tokens.append(Token('INT', int(value)))
        elif tok_type == 'BOOL':
            tokens.append(Token('BOOL', value == 'true'))
        elif tok_type == 'NAME':
            # Check for reserved keywords that look like names but shouldn't be
            reserved = {'fun', 'let', 'rec', 'in', 'if', 'then', 'else', 'true', 'false'}
            if value in reserved and value != 'true' and value != 'false':
                 # Treat reserved keywords as simple names for parsing simplicity, 
                 # the parser rules will enforce their usage.
                tokens.append(Token('NAME', value))
            else:
                tokens.append(Token('NAME', value))
        elif tok_type == 'SYMBOL':
            if value == '->':
                tokens.append(Token('TYPE_ARROW', value))
            elif value == '::':
                tokens.append(Token('LIST_CONCAT', value))
            elif value == '(':
                tokens.append(Token('LPAREN', value))
            elif value == ')':
                tokens.append(Token('RPAREN', value))
            elif value == ',':
                tokens.append(Token('COMMA', value))
            elif value == '+':
                tokens.append(Token('PLUS', value))
            elif value == '-':
                tokens.append(Token('MINUS', value))
            elif value == '*':
                tokens.append(Token('MULTIPLY', value))
            elif value == '<':
                tokens.append(Token('LT', value))
            elif value == '[':
                tokens.append(Token('EMPTY_LIST_START', value))
            elif value == ']':
                tokens.append(Token('EMPTY_LIST_END', value))
        else:
            raise SyntaxError(f"Unexpected token: {value}")

    return tokens

