class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return Token('EOF', None)

    def consume(self, expected_type: Optional[str] = None, expected_value: Optional[Any] = None) -> Token:
        token = self.tokens[self.pos]
        if expected_type and token.type != expected_type:
            raise SyntaxError(f"Expected {expected_type}, found {token.type}")
        if expected_value and token.value != expected_value:
            raise SyntaxError(f"Expected {expected_value}, found {token.value}")

        self.pos += 1
        return token

    def parse_literal(self) -> ASTNode:
        token = self.peek()
        if token.type == 'INT':
            self.consume('INT')
            return IntLiteral(int(token.value))
        elif token.type == 'BOOL':
            self.consume('BOOL')
            return BoolLiteral(bool(token.value))
        elif token.type == 'NAME':
            self.consume('NAME')
            return VarName(token.value)
        elif token.type == 'EMPTY_LIST_START':
            self.consume('EMPTY_LIST_START')
            self.consume('EMPTY_LIST_END')
            return ListLiteral(VarName("[]")) # Placeholder for empty list
        else:
            raise SyntaxError("Expected literal (Int, Bool, Name, or [])")

