        elif token.type == 'NAME':
            return self.parse_literal()
        elif token.type == 'EMPTY_LIST_START':
            return self.parse_literal()
        elif token.type == 'LPAREN':
            self.consume('LPAREN')
            expr = self.parse_expr()
            self.consume('RPAREN')
            return expr # Treat (E) as E
