                    # This structure is too complex for a simple parser implementation; 
                    # assume the calling parse_expr handles the structural recognition.
                    pass # Rely on explicit structured parsing below.

                # Assume simple binding: let x = e1 in e2
                value = self.parse_expr()
                self.consume('NAME', 'in') # Consume 'in'
                body = self.parse_expr()

                return LetBinding(name, value, body)

            elif name == 'fun':
                # Special case for 'let f = fun ...'
                return self.parse_fun_def_wrapped(name)

            elif name == 'if':
                self.consume('NAME') # Consume 'if'
                self.consume('NAME', '(', or 'true') # Consume condition
                then_b = self.parse_expr()
                self.consume('NAME', 'then')
                else_b = self.parse_expr()
                return IfExpr(self.consume('NAME', 'in').body, then_b, else_b)

        elif token.type == 'LPAREN':
            return self.parse_tuple_or_group()

        raise SyntaxError(f"Unrecognized structure starting at {token}")

    def parse_tuple_or_group(self) -> ASTNode:
        self.consume('LPAREN')

        start_pos = self.pos

        # Peek at the next token to decide if it's a tuple or a grouping
        next_token = self.peek()

        # If the first token is a name (and not followed by an assignment/in), it might be a grouping.
        # Since the grammar states ( e ), we treat this as expression grouping first.

        elements: List[ASTNode] = []

        while self.peek().type != 'RPAREN':
            if self.peek().type == 'COMMA':
                self.consume('COMMA')
                if self.peek().type == 'RPAREN': break # Should not happen

            # This logic handles both (e1, e2) and simple grouping (e1)
            if self.peek().type == 'COMMA': # Should be handled by comma token
                break

            # To correctly distinguish (e1, e2) from (e1) which is just grouping,
            # we rely on checking if a comma is expected.

            elements.append(self.parse_expr())

            if self.peek().type == 'COMMA':
                self.consume('COMMA')

        self.consume('RPAREN')

        if len(elements) > 1:
            # Multiple elements means tuple (e1, e2)
            return TupleExpr(elements)
        elif len(elements) == 1:
            # Single element means grouping (e1)
            return elements[0]
        else:
            raise SyntaxError("Empty parentheses")

    def parse_fun_def_wrapped(self, func_name: str) -> ASTNode:
        """Handles 'let f = fun x -> e in e'' structure."""
        self.consume('NAME', func_name) # Consume the function name f
        self.consume('EQUALS') # Consume '='

        # The rest is a function definition (fun x -> e)
        fun_def_node = self.parse_fun_def()

        # Note: The binding structure is complex. We treat (let f = E in E') 
        # The actual AST definition for `let` must use the name 'f', and the value 
        # is the FunDef node.

        return LetBinding(func_name, fun_def_node, self.parse_expr())


    def parse_fun_def(self) -> FunDef:
        """Core parsing for fun x1 x2 ... -> e"""
        # 1. Get parameters
        params = []
        while self.peek().type == 'NAME' and self.tokens[self.pos].value not in ('fun', 'let', 'rec'):
            params.append(self.consume('NAME').value)

        self.consume('TYPE_ARROW') # Consume '->'

        # 2. Get body
        body = self.parse_expr()
        return FunDef(params, body)

    def parse_list_literal(self) -> ASTNode:
        """Handles [] syntax."""
        # We treat [] as a special type variable placeholder, as defined in the grammar.
        self.consume('EMPTY_LIST_START')
        self.consume('EMPTY_LIST_END')
        return ListLiteral(VarName("[]"))


    def parse_binary_op(self, op_tokens: List[str]) -> ASTNode:
        """Handles low precedence operators: +, -, *, <"""
        # This is highly simplified, assuming left-to-right parsing based on precedence.

        left = self.parse_expr()

        current_op = None

        # This loop must handle repeated application (a + b + c)
        while self.peek().type in (op_tokens[0].upper(), op_tokens[-1].upper()): # e.g., PLUS, MINUS
            op_token = self.peek()
            if op_token.type not in ('PLUS', 'MINUS', 'MULTIPLY', 'LT'): # Simplified check
                break

            op = op_token.value
            self.consume(expected_type=op_token.type)

            right = self.parse_expr()

            # left = (left op right)
            left = BinOp(op, left, right)

        return left

    def parse_expr(self) -> ASTNode:
        """Main expression parser, handling precedence (Operator Precedence Parsing)."""
        # 1. Primary (Literal, Grouping, Name)
        node = self.parse_primary()

        # 2. Assignment/Comparison (e1 = e2, e1 < e2) - High precedence handled by consume
        if self.peek().type == 'EQUALS': # Assuming '=' is parsed as a named token for simplicity
             self.consume('EQUALS')
             right_node = self.parse_expr()
             return BinOp('=', node, right_node)
        if self.peek().type == 'LT':
             self.consume('LT')
             right_node = self.parse_expr()
             return BinOp('<', node, right_node)

        # 3. List Concatenation (e1 :: e2)
        if self.peek().type == 'LIST_CONCAT':
            self.consume('LIST_CONCAT')
            right_node = self.parse_expr()
            return BinOp('::', node, right_node)

        # 4. Multiplication (*)
        if self.peek().type == 'MULTIPLY':
            self.consume('MULTIPLY')
            right_node = self.parse_expr()
            return BinOp('*', node, right_node)

        # 5. Addition/Subtraction/Comparison (Lowest precedence)

        # We rely on the structural flow: if it wasn't a primary, and it's followed by
        # +, -, or another low-precedence operator, we handle it.

        while self.peek().type in ('PLUS', 'MINUS'):
            op_token = self.peek()
            op = op_token.value
            self.consume(expected_type=op_token.type)

            right_node = self.parse_expr()
            node = BinOp(op, node, right_node)

        return node

