# Environment: Maps names to Type Schemes (Type Variable -> Type)
Environment = Dict[str, Type] 

class TypeScheme:
    """Represents a quantified type: Type[a, b] -> T"""
    def __init__(self, type_t: Type, env: Environment):
        self.type = type_t
        self.env = env

    def instantiate(self, fresh_vars: List[str]) -> Type:
        """Replaces type variables with fresh, unique types."""
        current_sub = Substitution()
        for i, var_name in enumerate(fresh_vars):
            # Rebind type variables encountered in the scheme's environment
            current_sub.bindings[var_name] = TypeVar.fresh()

        return self.type.apply(current_sub, self.type)

def generalize(type_t: Type, env: Environment) -> TypeScheme:
    """
    Generalizes a type, quantifying all type variables that are free in type_t
    but not free in the current environment env.
    """
    # For simplicity, we assume variables free in the environment are only
    # the initial built-in names (fst, snd, hd, tl, null).

    # In a full HM implementation, this requires complex tracking of free variables.
    # Here, we treat any variable appearing in the type (which is not 
    # one of the function arguments) as a potential type variable 'a', 'b', etc.

    return TypeScheme(type_t, env)

def infer(ast: ASTNode, env: Environment) -> Type:
    """
    Performs the core type inference worker.
    Returns the inferred Type object.
    """
    if isinstance(ast, IntLiteral):
        return Type.make_primitive("int")
    if isinstance(ast, BoolLiteral):
        return Type.make_primitive("bool")
    if isinstance(ast, VarName):
        if ast.name in env:
            # Lookup the full type instance from the environment
            # This is where type schemas (let) must be handled.
            return env[ast.name]
        else:
            # Undefined name
            raise NameError(f"Variable '{ast.name}' is not defined.")

    # 1. Tuple/Grouping (e1, e2)
    if isinstance(ast, TupleExpr):
        inferred_types: List[Type] = []
        sub = Substitution()
        for element in ast.elements:
            # Recursively infer, propagating the same environment
            inferred_types.append(infer(element, env))
        # Product type
        return Type.make_product(inferred_types)

    # 2. List Literal (The '[]' placeholder)
    if isinstance(ast, ListLiteral):
        # Represents the type 'a list' where 'a' is fresh
        return Type.make_list(TypeVar.fresh())

    # 3. Binary Operation (e1 + e2, e1 < e2, etc.)
    if isinstance(ast, BinOp):
        left_t = infer(ast.left, env)
        right_t = infer(ast.right, env)

        if ast.op == '+':
            # T + T -> T
            t = Type.make_func(left_t, [left_t]) # Type structure needs refinement here
            # Given the problem rule: int -> int -> int
            if left_t.name != 'int' or right_t.name != 'int':
                raise TypeError(f"Operator '+' requires two 'int' arguments, got {left_t} and {right_t}")
            return Type.make_func(left_t, [left_t])

        elif ast.op == '-':
